}

#stock-table tbody tr:hover {
    background-color: #f0f7ff;
}

#stock-table tr.highlighted {
    background-color: #ffe082 !important;
    font-weight: bold;
}

#stock-table tr:nth-child(even) {
    background-color: #f9f9f9;
}
EOF
