{
  "analysis": "CSS file created successfully. Now I need to create the main visualization.js file which will contain the D3.js code for the bubble chart with force simulation and the data table with interactivity.",
  "plan": "Create the visualization.js file with: 1) Data loading from CSV, 2) Bubble chart with force simulation (forceX, forceY, forceCollide) to cluster by sector, 3) Color scale for sectors, 4) Market cap-based sizing, 5) Tooltip on hover (excluding ETFs), 6) Data table, 7) Click interactivity between chart and table.",
  "commands": [
    {
      "keystrokes": "cat > js/visualization.js << 'EOF'
// Global variables
let stockData = [];
let selectedTicker = null;

// Format market cap for display
function formatMarketCap(value) {
    if (!value || value === '' || isNaN(value)) return 'N/A';
    const num = parseFloat(value);
    if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
    if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
    if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
    return num.toFixed(2);
}

// Load and process data
d3.csv('data/stock-descriptions.csv').then(data => {
    // Process the data
    stockData = data.map(d => ({
        ticker: d.ticker,
        sector: d.sector || 'Unknown',
        fullName: d['full name'] || d.ticker,
        marketCap: parseFloat(d.marketCap) || null,
        country: d.country,
        website: d.website
    }));

    // Create visualizations
    createBubbleChart();
    createTable();
});

function createBubbleChart() {
    const width = 800;
    const height = 700;

    // Get unique sectors and create color scale
    const sectors = [...new Set(stockData.map(d => d.sector))];
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeTableau10);

    // Create SVG
    const svg = d3.select('#bubble-chart')
        .append('svg')
        .attr('width', width)
        .attr('height', height);

    // Calculate bubble sizes
    const marketCaps = stockData.filter(d => d.marketCap).map(d => d.marketCap);
    const minMarketCap = d3.min(marketCaps);
    const maxMarketCap = d3.max(marketCaps);

    const radiusScale = d3.scaleSqrt()
        .domain([minMarketCap, maxMarketCap])
        .range([15, 50]);

    // Add radius to data
    stockData.forEach(d => {
        d.radius = d.marketCap ? radiusScale(d.marketCap) : 20; // ETFs get uniform size
    });

    // Create sector positions for clustering
    const sectorPositions = {};
    const numSectors = sectors.length;
    const cols = Math.ceil(Math.sqrt(numSectors));
    sectors.forEach((sector, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        sectorPositions[sector] = {
            x: (col + 0.5) * (width / cols),
            y: (row + 0.5) * (height / Math.ceil(numSectors / cols))
        };
    });

    // Create force simulation
    const simulation = d3.forceSimulation(stockData)
        .force('charge', d3.forceManyBody().strength(5))
        .force('x', d3.forceX(d => sectorPositions[d.sector].x).strength(0.3))
        .force('y', d3.forceY(d => sectorPositions[d.sector].y).strength(0.3))
        .force('collide', d3.forceCollide(d => d.radius + 2))
        .force('center', d3.forceCenter(width / 2, height / 2).strength(0.05));

    // Create bubbles
    const bubbles = svg.selectAll('.bubble')
        .data(stockData)
        .enter()
        .append('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.radius)
        .attr('fill', d => colorScale(d.sector))
        .attr('stroke', '#fff')
        .attr('stroke-width', 1.5)
        .on('mouseover', function(event, d) {
            // Only show tooltip for non-ETF stocks (those with marketCap)
            if (d.marketCap) {
                const tooltip = d3.select('#tooltip');
                tooltip.html(`
                    <strong>${d.ticker}</strong><br/>
                    ${d.fullName}<br/>
                    Sector: ${d.sector}
                `)
                .style('left', (event.pageX + 10) + 'px')
                .style('top', (event.pageY - 10) + 'px')
                .classed('visible', true);
            }
        })
        .on('mouseout', function() {
            d3.select('#tooltip').classed('visible', false);
        })
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    // Add labels
    const labels = svg.selectAll('.bubble-label')
        .data(stockData)
        .enter()
        .append('text')
        .attr('class', 'bubble-label')
        .text(d => d.ticker)
        .style('font-size', d => Math.min(d.radius / 3, 12) + 'px');

    // Update positions on simulation tick
    simulation.on('tick', () => {
        bubbles
            .attr('cx', d => d.x)
            .attr('cy', d => d.y);

        labels
            .attr('x', d => d.x)
            .attr('y', d => d.y);
    });

    // Create legend
    const legend = d3.select('#legend');
    sectors.forEach(sector => {
        const item = legend.append('div')
            .attr('class', 'legend-item');

        item.append('div')
            .attr('class', 'legend-color')
            .style('background-color', colorScale(sector));

        item.append('span')
            .text(sector);
    });
}

function createTable() {
    const table = d3.select('#stock-table')
        .append('table');

    // Create header
    const thead = table.append('thead');
    thead.append('tr')
        .selectAll('th')
        .data(['Ticker Symbol', 'Full Company Name', 'Sector', 'Market Cap'])
        .enter()
        .append('th')
        .text(d => d);

    // Create body
    const tbody = table.append('tbody');
    const rows = tbody.selectAll('tr')
        .data(stockData)
        .enter()
        .append('tr')
        .attr('data-ticker', d => d.ticker)
        .on('click', function(event, d) {
            selectStock(d.ticker);
        });

    rows.selectAll('td')
        .data(d => [
            d.ticker,
            d.fullName,
            d.sector,
            formatMarketCap(d.marketCap)
        ])
        .enter()
        .append('td')
        .text(d => d);
}

function selectStock(ticker) {
    selectedTicker = ticker;

    // Highlight bubble
    d3.selectAll('.bubble')
        .attr('stroke', d => d.ticker === ticker ? '#ff6b6b' : '#fff')
        .attr('stroke-width', d => d.ticker === ticker ? 3 : 1.5);

    // Highlight table row
    d3.selectAll('#stock-table tbody tr')
        .classed('highlighted', function() {
            return d3.select(this).attr('data-ticker') === ticker;
        });

    // Scroll to highlighted row
    const highlightedRow = d3.select(`#stock-table tbody tr[data-ticker="${ticker}"]`).node();
    if (highlightedRow) {
        highlightedRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
}
